    // dependencies come from the repo's hash-pinned uv.lock.
    {
      method: "shell.run",
      params: {
        env: { UV_PYTHON_INSTALL_DIR: ".python", UV_CACHE_DIR: ".uv-cache", UV_PROJECT_ENVIRONMENT: "env", UV_NO_CONFIG: "1" },
        message: ["uv sync --frozen --python 3.14"],
      },
    },
    // Web dashboard + the terminal chat it embeds (built once, served by Python).
    {
      method: "shell.run",
      params: {
        env: { npm_config_cache: ".npm-cache" },
        message: [
          "npm install --workspace web --workspace ui-tui --no-audit --no-fund",
          "npm run build -w web",
          "npm run build -w ui-tui",
        ],
      },
    },
  ],
}

