scripts.install.js:
// OpenClaw needs Node 24 (Obstat ships 22), so a private Node 24 comes from the npm
// registry into runtime/, then OpenClaw 2026.10.5 (the version of the reviewed commit).
const os = require("os")
const win = os.platform() === "win32"
const NODE_PKG = win ? "node-win-x64" : os.platform() === "darwin" ? (os.arch() === "arm64" ? "node-darwin-arm64" : "node-darwin-x64") : "node-linux-x64"
const USE_NODE24 = win ? `set "PATH=%CD%\\node_modules\\${NODE_PKG}\\bin;%PATH%"` : `export PATH="$PWD/node_modules/${NODE_PKG}/bin:$PATH"`
const DATA_HOME = win ? `set "OPENCLAW_HOME=%CD%\\..\\data"` : `export OPENCLAW_HOME="$PWD/../data"`
const LOG_FILE = win ? `"%CD%\\..\\data\\logs\\openclaw.log"` : `"$PWD/../data/logs/openclaw.log"`
const OC = "node node_modules/openclaw/openclaw.mjs"
const ENV = { npm_config_cache: ".npm-cache", NO_COLOR: "1", OPENCLAW_TELEMETRY: "0", OPENCLAW_NO_AUTO_UPDATE: "1", OPENCLAW_DISABLE_BONJOUR: "1" }
module.exports = {
  run: [
    { method: "shell.run", params: { path: "runtime", env: ENV, message: [
      "npm init -y",
      `npm install --no-audit --no-fund --save-exact ${NODE_PKG}@24.22.0`,
    ] } },
    { method: "shell.run", params: { path: "runtime", env: ENV, message: [
      USE_NODE24,
      "npm install --no-audit --no-fund --save-exact openclaw@2026.10.5",
    ] } },
    // Local-only gateway config, kept in <app>/data/.openclaw (not ~/.openclaw); logs in <app>/data/logs.
    { method: "shell.run", params: { path: "runtime", env: ENV, message: [
      USE_NODE24,
      DATA_HOME,
      `${OC} config set logging.file ${LOG_FILE}`,
      `${OC} config set gateway.mode local`,
      `${OC} config set gateway.bind loopback`,
      `${OC} config set update.checkOnStart false`,
    ] } },
  ],
}

scripts.start.js:
const os = require("os")
const win = os.platform() === "win32"
const NODE_PKG = win ? "node-win-x64" : os.platform() === "darwin" ? (os.arch() === "arm64" ? "node-darwin-arm64" : "node-darwin-x64") : "node-linux-x64"
const USE_NODE24 = win ? `set "PATH=%CD%\\node_modules\\${NODE_PKG}\\bin;%PATH%"` : `export PATH="$PWD/node_modules/${NODE_PKG}/bin:$PATH"`
const DATA_HOME = win ? `set "OPENCLAW_HOME=%CD%\\..\\data"` : `export OPENCLAW_HOME="$PWD/../data"`
module.exports = {
  daemon: true,
  run: [
    // A fresh random gateway token each start; it is handed to the browser in the URL fragment.
    { method: "local.set", params: { token: "{{[0,0,0,0,0,0].map(function(){return Math.random().toString(36).slice(2,10)}).join('')}}" } },
    {
      method: "shell.run",
      params: {
        path: "runtime",
        env: {
          NO_COLOR: "1", FORCE_COLOR: "0",
          OPENCLAW_TELEMETRY: "0", OPENCLAW_NO_AUTO_UPDATE: "1", OPENCLAW_DISABLE_BONJOUR: "1",
          OPENCLAW_GATEWAY_TOKEN: "{{local.token}}",
        },
        message: [
          USE_NODE24,
          DATA_HOME,
          "node node_modules/openclaw/openclaw.mjs gateway run --bind loopback --auth token --port {{port}}",
        ],
        on: [{ event: "/\\[gateway\\] ready/", done: true }],
      },
    },
    { method: "local.set", params: { url: "http://127.0.0.1:{{port}}/#token={{local.token}}" } },
  ],
}

