scripts.start.js:
// Open WebUI's logging hides uvicorn's "running on" line, so a tiny wrapper starts the
// normal `open-webui serve` command and prints the URL once the server really answers.
const LAUNCH = "python -c \"import sys,time,threading,urllib.request as u;p=sys.argv[1];h='http://127.0.0.1:'+p;" +
  "exec('def w():\\n while 1:\\n  try:\\n   u.build_opener(u.ProxyHandler({})).open(h,timeout=5);print(h,flush=True);return\\n  except Exception:\\n   time.sleep(1)');" +
  "threading.Thread(target=w,daemon=True).start();sys.argv=['open-webui','serve','--host','127.0.0.1','--port',p];" +
  "from open_webui import app;app()\" {{port}}"
module.exports = {
  daemon: true,
  run: [
    {
      method: "shell.run",
      params: {
        venv: "env",
        env: {
          DATA_DIR: "data",
          HF_HOME: "data/huggingface",
          SENTENCE_TRANSFORMERS_HOME: "data/huggingface",
          SCARF_NO_ANALYTICS: "true",
          DO_NOT_TRACK: "true",
          ANONYMIZED_TELEMETRY: "false",
          ENABLE_VERSION_UPDATE_CHECK: "false",
          NO_COLOR: "1",
          FORCE_COLOR: "0",
        },
        message: [LAUNCH],
        on: [{ event: "/(http:\\/\\/127\\.0\\.0\\.1:[0-9]+)/", done: true }],
      },
    },
    { method: "local.set", params: { url: "{{input.event[1]}}" } },
  ],
}

