  daemon: true,
  run: [
    {
      method: "shell.run",
      params: {
        venv: "env",
        env: { NO_COLOR: "1", FORCE_COLOR: "0", COLUMNS: "200" },
        // --home keeps config, sessions, memory and workspace in <app>/data (not ~/.nanobot);
